<template><div class="page">
 <div class="page-header"><div><div class="page-title">基础字典管理</div><div class="text-muted subtitle">统一维护铺位使用的楼层、业态和工程参数</div></div><el-button type="primary" @click="openCreate">新增{{typeLabel}}</el-button></div>
 <el-tabs v-model="type" @tab-change="load"><el-tab-pane v-for="t in types" :key="t.value" :label="t.label" :name="t.value"/></el-tabs>
 <div v-if="type!=='CABLE'" class="table-card"><el-table :data="rows" v-loading="loading" border>
  <el-table-column prop="itemValue" label="取值编码" min-width="140"/><el-table-column prop="itemLabel" label="显示名称" min-width="160"/><el-table-column prop="sortOrder" label="排序" width="90"/>
  <el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column>
  <el-table-column prop="remark" label="备注" min-width="180"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="删除后历史数据仍保留原值，确定删除？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column>
 </el-table></div>
 <div v-else class="table-card"><el-table :data="cableRows" v-loading="loading" border>
  <el-table-column prop="specCode" label="规格编码" min-width="120"/><el-table-column prop="cableModel" label="电缆型号" min-width="130"/><el-table-column prop="specification" label="规格" min-width="180"/><el-table-column prop="ratedCurrentA" label="单根额定电流(A)" min-width="135"/><el-table-column prop="ratedPowerKw" label="单根承载功率(kW)" min-width="150"/>
  <el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注" min-width="180"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="已被铺位使用的规格不能删除，可改为停用。确定删除？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column>
 </el-table></div>
 <el-dialog v-model="visible" :title="form.id?'编辑字典项':`新增${typeLabel}`" width="560px"><el-form ref="formRef" :model="form" :rules="type==='CABLE'?cableRules:rules" label-width="130px">
  <template v-if="type==='CABLE'"><el-form-item label="规格编码" prop="specCode"><el-input v-model="form.specCode" placeholder="例如：YJV-4X35-1X16"/></el-form-item><el-form-item label="电缆型号" prop="cableModel"><el-input v-model="form.cableModel" placeholder="例如：YJV"/></el-form-item><el-form-item label="规格" prop="specification"><el-input v-model="form.specification" placeholder="例如：4×35+1×16 mm²"/></el-form-item><el-form-item label="单根额定电流" prop="ratedCurrentA"><el-input-number v-model="form.ratedCurrentA" :min="0.01" :precision="2"/><span class="unit">A</span></el-form-item><el-form-item label="单根承载功率" prop="ratedPowerKw"><el-input-number v-model="form.ratedPowerKw" :min="0.01" :precision="2"/><span class="unit">kW</span></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></template>
  <template v-else>
  <el-form-item label="分类"><el-input :model-value="typeLabel" disabled/></el-form-item><el-form-item label="取值编码" prop="itemValue"><el-input v-model="form.itemValue" placeholder="例如：F1"/></el-form-item><el-form-item label="显示名称" prop="itemLabel"><el-input v-model="form.itemLabel" placeholder="例如：一层"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item>
  </template>
 </el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,type FormInstance}from'element-plus';import{dictionaryApi,cableSpecificationApi,type CableSpecification,type DictionaryItem,type DictionaryType}from'@/api/system'
type PageType=DictionaryType|'CABLE';const types=[{value:'FLOOR',label:'楼层'},{value:'BUSINESS_TYPE',label:'业态'},{value:'CABLE',label:'电缆规格'}] as {value:PageType,label:string}[]
const type=ref<PageType>('FLOOR'),rows=ref<DictionaryItem[]>([]),cableRows=ref<CableSpecification[]>([]),loading=ref(false),saving=ref(false),visible=ref(false),formRef=ref<FormInstance>();const form=reactive<any>({});const typeLabel=computed(()=>types.find(t=>t.value===type.value)?.label||'')
const rules={itemValue:[{required:true,message:'请输入取值编码'}],itemLabel:[{required:true,message:'请输入显示名称'}]}
const cableRules={specCode:[{required:true,message:'请输入规格编码'}],cableModel:[{required:true,message:'请输入电缆型号'}],specification:[{required:true,message:'请输入电缆规格'}],ratedCurrentA:[{required:true,message:'请输入额定电流'}],ratedPowerKw:[{required:true,message:'请输入承载功率'}]}
async function load(){loading.value=true;try{if(type.value==='CABLE')cableRows.value=await cableSpecificationApi.list(false) as any;else rows.value=await dictionaryApi.list(type.value,false) as any}finally{loading.value=false}}
function openCreate(){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,type.value==='CABLE'?{id:0,specCode:'',cableModel:'',specification:'',ratedCurrentA:null,ratedPowerKw:null,sortOrder:0,status:1,remark:''}:{id:0,itemValue:'',itemLabel:'',sortOrder:0,status:1,remark:''});visible.value=true}function openEdit(row:any){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row);visible.value=true}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{if(type.value==='CABLE'){const data={specCode:form.specCode,cableModel:form.cableModel,specification:form.specification,ratedCurrentA:form.ratedCurrentA,ratedPowerKw:form.ratedPowerKw,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await cableSpecificationApi.update(form.id,data);else await cableSpecificationApi.create(data)}else{const data={dictType:type.value,itemValue:form.itemValue,itemLabel:form.itemLabel,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await dictionaryApi.update(form.id,data);else await dictionaryApi.create(data)}ElMessage.success('保存成功');visible.value=false;await load()}finally{saving.value=false}}
async function remove(row:any){if(type.value==='CABLE')await cableSpecificationApi.remove(row.id);else await dictionaryApi.remove(row.id);ElMessage.success('删除成功');await load()}onMounted(load)
</script><style scoped>.subtitle{font-size:13px;margin-top:4px}.unit{margin-left:8px;color:#606266}</style>
